INSERT INTO dbo.Banner (banner_name, banner_title, banner_description, banner_status, link_banner, href_banner) 
VALUES 
('banner1', N'Dịch vụ nhãn khoa từ Nhật Bản', N'Từ Nhật Bản, chúng tôi mang đến dịch vụ y tế tiêu chuẩn quốc tế với mong muốn mỗi bệnh nhân đều được trải nghiệm sự chăm sóc chu đáo, thăm khám và điều trị bằng những phương pháp tiên tiến nhất.', 'true', 'https://res.cloudinary.com/djmftornv/image/upload/v1738735993/banner/teig1usvmsnbavavbrck.jpg', 'trangchu'), 
('banner2', N'Thăm khám với Bác sỹ đầu ngành', N'Mọi bệnh nhân đều xứng đáng được điều trị bằng những phương pháp hiện đại, tối ưu nhất, chúng tôi hiểu và luôn nỗ lực vì điều đó.', 'true', 'https://res.cloudinary.com/djmftornv/image/upload/v1738736003/banner/fotnuc6q51rwhk9rkun5.jpg', 'trangchu'), 
('banner3', N'Công nghệ, thiết bị điều trị tiên tiến', N'Bởi hiểu rằng đôi mắt là cánh cửa kết nối chúng ta với thế giới xung quanh, nên chúng tôi luôn nỗ lực để mỗi bệnh nhân được tự do khám phá và tận hưởng trọn vẹn cuộc sống bằng đôi mắt sáng khỏe.', 'true', 'https://res.cloudinary.com/djmftornv/image/upload/v1738736134/banner/kqco2frqlx3kihljkqsn.png', 'trangchu'), 
('banner4', N'An yên tận hưởng tuổi xế chiều', N'Chúng tôi nỗ lực để cùng bệnh nhân lấy lại đôi mắt sáng khỏe ở tuổi xế chiều để họ an yên tận hưởng mọi khoảnh khắc của cuộc sống bởi chúng tôi tin rằng họ xứng đáng.', 'true', 'https://res.cloudinary.com/djmftornv/image/upload/v1738736297/banner/f2a8numr5n4n2om6xete.jpg', 'trangchu'), 
('banner5', N'Tự do khám phá thế giới', N'Bởi hiểu rằng đôi mắt là cánh cửa kết nối chúng ta với thế giới xung quanh, nên chúng tôi luôn nỗ lực để mỗi bệnh nhân được tự do khám phá và tận hưởng trọn vẹn cuộc sống bằng đôi mắt sáng khỏe.', 'true', 'https://res.cloudinary.com/djmftornv/image/upload/v1738736344/banner/zykj3oqa13kcskcluap3.jpg', 'trangchu'), 
('banner6', N'Tự do tận hưởng đam mê thể thao', N'Hãy để chúng tôi cùng bạn loại bỏ sự phiền toái của kính gọng hay kính áp tròng để tự do tham gia các môn thể thao yêu thích và tận hưởng mọi đam mê, sở thích.', 'true', 'https://res.cloudinary.com/djmftornv/image/upload/v1738736414/banner/xwa2ifvpyhwjpv2exvrr.jpg', 'trangchu');